"""Labelled training data, generated by driving the real simulator.

No feature value in this module is written by hand. Every row is one telemetry
frame produced by `SimulationSession.step()`, which means the training data is
produced by exactly the same physics, thermal model, vibration synthesis and
sensor models that the live service will feed the classifier at run time. A
hand-authored "imbalance looks like 6 mm/s at 1x" table would train the model on
the label it is supposed to predict.

Four rules decide which frames become rows, and each exists because breaking it
produces a model that is worse than useless.

1. RUNNING ONLY.  A severe fault trips the SCADA interlocks: cavitation drives
   suction pressure under the low-suction trip, the machine stops after the
   10 s on-delay and coasts to FAULT with zero flow and zero vibration. Those
   frames are samples of a *stopped pump*, not of cavitation. Keeping them
   teaches the classifier "cavitation = everything is zero", which then fires on
   every genuinely stopped machine and never on a cavitating one.

2. DEVELOPED ONLY.  Faults ramp in with a first-order lag, so the first seconds
   after injection are physically almost healthy while already carrying the
   fault label. A frame is kept only once the simulator reports at least
   `DEVELOPED_FRACTION` of the target severity, which also gives every run a
   natural spread of severities between that fraction and the target.

3. INSTRUMENT ACTUALLY LYING.  Arming a fault on a transmitter is not the same
   as the transmitter being wrong in this frame. A `dropout` reads correctly
   between bursts; a `drift` that has accumulated 0.02 A is still, to any
   measurable extent, correct. Those frames contain no evidence of an
   instrument fault, so a `sensor_fault` label on them is not a hard example,
   it is a wrong one -- and because they sit exactly on top of the healthy
   cloud, they cost the `normal` class its precision. A sensor-fault frame is
   kept only when the armed instrument's reading departs from the true process
   value (`SimulationSession.truth`) by more than three times its own healthy
   noise. That still leaves plenty of hard cases: the model has to catch the
   lie through the physics tying the channels together, which needs a far
   larger error than three sigma of the instrument itself.

4. THE LABEL IS THE SIMULATOR'S TRUTH.  `Telemetry.fault_state` is the injected
   condition, not an inference from the data.

`freeze` is deliberately not among the injected sensor modes. A frozen
transmitter under steady conditions reports the correct value; it is only
detectable across time, and this feature vector is a single frame. Training on
it would inject frames indistinguishable from `normal` into the `sensor_fault`
class and damage both. `diagnosis.py` catches a frozen channel from its
UNCERTAIN quality flag instead, which is where that detection belongs.

Determinism: every run's session id, and therefore every noise stream in the
simulator, is derived from a fixed seed, so re-running this module produces a
byte-identical dataset.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

from ..config.pump_parameters import ASSET
from ..config.sensor_parameters import SENSORS
from ..contracts import FEATURE_ORDER, AssetState, FaultType, Telemetry
from ..simulation.engine import SimulationSession
from .inference import feature_vector

# --------------------------------------------------------------------------
# Generation parameters
# --------------------------------------------------------------------------

#: Master seed. Everything random in this module descends from it.
DATASET_SEED: int = 20260812

#: Warm-up is stepped coarsely: the thermal states have 300-420 s time
#: constants, so reaching a spread of temperatures needs minutes of simulated
#: time. The thermal model uses an exact exponential update and is stable at any
#: dt, so a 1 s step costs nothing in fidelity here.
WARMUP_DT_S: float = 1.0
#: Sampling is stepped finely, because the interlock on-delays that decide when
#: a tripping fault stops the machine are resolved in tenths of a second.
SAMPLE_DT_S: float = 0.2
#: One kept frame per second of simulated time. Consecutive ticks are almost
#: identical, so a smaller stride would add rows without adding information.
SAMPLE_STRIDE: int = 5
#: Frames wanted from each run.
FRAMES_PER_RUN: int = 24
#: Hard cap on sampling ticks, so a run that never qualifies still terminates.
MAX_SAMPLE_TICKS: int = 600
#: A frame counts as carrying its fault once severity reaches this fraction of
#: the injected target.
DEVELOPED_FRACTION: float = 0.6

RPM_CHOICES: tuple[float, ...] = (1100.0, 1180.0, 1250.0, 1320.0, 1400.0, 1450.0, 1500.0)
VALVE_CHOICES: tuple[float, ...] = (0.30, 0.45, 0.60, 0.75, 0.90, 1.00)
#: Seconds of running before the fault is injected. The spread is what puts
#: temperature variety in the dataset: 30 s is barely off ambient, 900 s is
#: close to the steady-state rise.
WARMUP_CHOICES: tuple[float, ...] = (30.0, 90.0, 240.0, 480.0, 900.0)

#: Severity grids. The low end is deliberately close to the decision boundary:
#: a 0.15 imbalance is a real but small defect and the model should be measured
#: on it rather than only on textbook-severe faults.
SEVERITY_CHOICES: tuple[float, ...] = (0.15, 0.25, 0.35, 0.50, 0.65, 0.80, 0.95)
#: Cavitation is split on purpose. Below about 0.45 the suction restriction is
#: developing but the NPSH margin is still positive -- a real and diagnosable
#: state. Above it the margin goes negative, the pump cavitates hard, and the
#: low-suction interlock stops the machine roughly ten seconds later, so those
#: runs contribute a short window of genuinely cavitating frames.
CAVITATION_SEVERITY_CHOICES: tuple[float, ...] = (0.25, 0.30, 0.35, 0.40, 0.50, 0.60, 0.75, 0.90, 1.00)
#: Dry run is capped below 1.0: at full severity the flow falls under the
#: no-flow interlock and the machine trips out of the class before the ramp has
#: finished developing.
DRY_RUN_SEVERITY_CHOICES: tuple[float, ...] = (0.15, 0.25, 0.35, 0.50, 0.65, 0.80, 0.90)

#: Instrument failure modes that are visible in a single frame. See the module
#: docstring for why `freeze` is not here.
SENSOR_MODES: tuple[str, ...] = ("bias", "drift", "noise", "dropout")

#: Channels a single frame can catch lying, and the reason the list stops where
#: it does. A wrong reading is only detectable in one frame if the rest of the
#: frame contradicts it. Speed, flow, both pressures, current and vibration are
#: tied to each other by the pump curve and the affinity laws, so a bias on any
#: of them puts the frame off the machine's own characteristic and can be
#: caught. The two temperatures are not: the thermal states have 300-420 s time
#: constants, so a valid motor temperature depends on how long the machine has
#: been running at what load -- history this feature vector does not carry. A
#: five-degree bias on TT-101 is therefore indistinguishable from a machine that
#: started five minutes earlier, and training on it does not make the model able
#: to detect it; it only teaches the model that healthy frames are sometimes
#: called `sensor_fault`, which costs the healthy class its precision.
#: `diagnosis.py` still reports those faults, from the quality flag.
SENSOR_TAGS: tuple[str, ...] = (
    ASSET.flow,
    ASSET.suction_pressure,
    ASSET.discharge_pressure,
    ASSET.current,
    ASSET.accelerometer,
    ASSET.speed,
)
#: Recorded so the exclusion is visible in the dataset metadata and model card
#: rather than only in this comment.
SENSOR_TAGS_EXCLUDED: dict[str, str] = {
    ASSET.motor_temperature: "thermal state depends on run history, which a single frame lacks",
    ASSET.bearing_temperature: "thermal state depends on run history, which a single frame lacks",
}

#: Instrument tag -> the key of the true process value it measures in
#: `SimulationSession.truth`, and the name of the reading on `Telemetry`. Used
#: by acceptance rule 3 to ask whether the instrument is actually lying.
_TRUTH_OF_TAG: dict[str, tuple[str, str]] = {
    ASSET.flow: ("flow_lpm", "flow_lpm"),
    ASSET.suction_pressure: ("suction_pressure_kpa", "suction_pressure_kpa"),
    ASSET.discharge_pressure: ("discharge_pressure_kpa", "discharge_pressure_kpa"),
    ASSET.current: ("motor_current_a", "motor_current_a"),
    ASSET.accelerometer: ("vibration_rms_mm_s", "vibration_rms_mm_s"),
    ASSET.speed: ("rpm", "rpm"),
}

#: Multiples of the instrument's own healthy noise beyond which its reading is
#: treated as carrying visible evidence of a fault.
SENSOR_LIE_SIGMA: float = 3.0

#: Runs per class.
#:
#: `normal` gets the most because it has the most ground to cover and the most
#: to lose. Every fault class occupies a region defined by a strong signature,
#: but the healthy class is the whole speed-by-valve operating grid, and it is
#: the class every other decision is measured against: a healthy machine
#: reported as faulty is the failure that makes an operator stop believing the
#: system. Cavitation and sensor faults get extra runs for the opposite reason
#: -- the interlocks cut their runs short, so a cavitation run yields roughly a
#: dozen usable frames against a healthy run's two dozen, and a dropout run
#: yields three.
RUNS_PER_CLASS: dict[str, int] = {
    FaultType.NORMAL.value: 160,
    FaultType.IMBALANCE.value: 70,
    FaultType.MISALIGNMENT.value: 70,
    FaultType.FLOW_RESTRICTION.value: 70,
    FaultType.CAVITATION.value: 130,
    FaultType.DRY_RUN.value: 70,
    FaultType.SENSOR_FAULT.value: 150,
}

#: Columns carried beside the feature vector. They are metadata for splitting
#: and auditing, never model inputs.
METADATA_COLUMNS: tuple[str, ...] = (
    "run_id",
    "label",
    "asset_state",
    "severity",
    "rpm_setpoint",
    "valve_opening",
    "sensor_tag",
    "sensor_mode",
    "elapsed_s",
)

DEFAULT_DATA_DIR = Path("data")
DATASET_FILENAME = "training_dataset.csv"
METADATA_FILENAME = "training_dataset_meta.json"


# --------------------------------------------------------------------------
# Run specification
# --------------------------------------------------------------------------


@dataclass(frozen=True)
class RunSpec:
    """One simulated run: a machine condition held while frames are sampled.

    The run, not the frame, is the unit of independence in this dataset. Frames
    inside one run share a noise stream, a thermal state and an operating point,
    so they must not be split across a train/test boundary.
    """

    run_id: str
    fault: str
    severity: float
    rpm: float
    valve: float
    warmup_s: float
    sensor_tag: str = ""
    sensor_mode: str = ""


def plan_runs(seed: int = DATASET_SEED) -> list[RunSpec]:
    """Every run to simulate, drawn deterministically from the condition grid.

    A random draw over the grid rather than its full cross product: the full
    product of fault x severity x speed x valve x warm-up is tens of thousands
    of runs for no extra coverage, because the operating space is smooth. The
    draw is seeded, so it is a fixed list, not a different one each time.
    """
    rng = np.random.default_rng(seed)
    runs: list[RunSpec] = []

    for fault_value, count in RUNS_PER_CLASS.items():
        fault = FaultType(fault_value)
        for index in range(count):
            rpm = float(rng.choice(RPM_CHOICES))
            valve = float(rng.choice(VALVE_CHOICES))
            warmup_s = float(rng.choice(WARMUP_CHOICES))
            tag = ""
            mode = ""

            if fault is FaultType.NORMAL:
                severity = 0.0
            elif fault is FaultType.SENSOR_FAULT:
                severity = float(rng.uniform(0.6, 1.0))
                tag = str(rng.choice(SENSOR_TAGS))
                mode = str(rng.choice(SENSOR_MODES))
            elif fault is FaultType.CAVITATION:
                severity = float(rng.choice(CAVITATION_SEVERITY_CHOICES))
            elif fault is FaultType.DRY_RUN:
                severity = float(rng.choice(DRY_RUN_SEVERITY_CHOICES))
            else:
                severity = float(rng.choice(SEVERITY_CHOICES))

            runs.append(
                RunSpec(
                    run_id=f"{fault_value}-{index:03d}",
                    fault=fault_value,
                    severity=severity,
                    rpm=rpm,
                    valve=valve,
                    warmup_s=warmup_s,
                    sensor_tag=tag,
                    sensor_mode=mode,
                )
            )
    return runs


# --------------------------------------------------------------------------
# Simulation of one run
# --------------------------------------------------------------------------


def simulate_run(spec: RunSpec) -> list[dict[str, float | str]]:
    """Start a machine, warm it, inject the condition, and sample frames.

    Returns only frames that pass every acceptance rule in the module
    docstring, which can legitimately be none -- a run whose interlocks stop
    the machine before the fault develops contributes nothing.
    """
    session = SimulationSession(spec.run_id)
    session.set_speed(spec.rpm)
    session.set_valve(spec.valve)
    session.command("start")

    for _ in range(int(spec.warmup_s / WARMUP_DT_S)):
        session.step(WARMUP_DT_S)

    if session.state != AssetState.RUNNING.value:
        # The machine never got to a steady running state; nothing this run
        # produces afterwards is a sample of the condition under test.
        return []

    if spec.fault != FaultType.NORMAL.value:
        if spec.fault == FaultType.SENSOR_FAULT.value:
            session.inject_fault(spec.fault, spec.severity, tag=spec.sensor_tag, mode=spec.sensor_mode)
        else:
            session.inject_fault(spec.fault, spec.severity)

    rows: list[dict[str, float | str]] = []
    for tick in range(MAX_SAMPLE_TICKS):
        telemetry = session.step(SAMPLE_DT_S)
        if telemetry.asset_state != AssetState.RUNNING.value:
            break  # rule 1: a tripped machine is not a sample of its fault
        if tick % SAMPLE_STRIDE:
            continue
        if not _is_acceptable(telemetry, spec, session.truth):
            continue
        rows.append(_row(telemetry, spec))
        if len(rows) >= FRAMES_PER_RUN:
            break
    return rows


def _is_acceptable(telemetry: Telemetry, spec: RunSpec, truth: dict[str, float]) -> bool:
    """Rules 2 and 3: the condition must actually be present in this frame."""
    if telemetry.fault_state != spec.fault:
        return False
    if spec.fault == FaultType.SENSOR_FAULT.value:
        return _instrument_is_lying(telemetry, spec.sensor_tag, truth)
    if spec.fault == FaultType.NORMAL.value:
        return True
    return telemetry.severity >= DEVELOPED_FRACTION * spec.severity


def _instrument_is_lying(telemetry: Telemetry, tag: str, truth: dict[str, float]) -> bool:
    """Is the armed transmitter's reading measurably wrong in this frame?

    Compares the reading against the true process value the simulator handed it.
    `SimulationSession.truth` is for diagnostics and tests only and nothing on
    the protection path may read it -- dataset generation is offline label
    construction, which is exactly the diagnostic use it exists for.
    """
    truth_key, reading_name = _TRUTH_OF_TAG[tag]
    error = abs(getattr(telemetry, reading_name) - truth[truth_key])
    return error > SENSOR_LIE_SIGMA * SENSORS[tag].noise_sigma


def _row(telemetry: Telemetry, spec: RunSpec) -> dict[str, float | str]:
    row: dict[str, float | str] = {
        "run_id": spec.run_id,
        "label": telemetry.fault_state,
        "asset_state": telemetry.asset_state,
        "severity": telemetry.severity,
        "rpm_setpoint": spec.rpm,
        "valve_opening": spec.valve,
        "sensor_tag": spec.sensor_tag,
        "sensor_mode": spec.sensor_mode,
        "elapsed_s": telemetry.elapsed_s,
    }
    row.update(dict(zip(FEATURE_ORDER, feature_vector(telemetry).tolist())))
    return row


# --------------------------------------------------------------------------
# Dataset
# --------------------------------------------------------------------------


def build_dataset(seed: int = DATASET_SEED) -> tuple[pd.DataFrame, dict]:
    """Simulate every planned run and return the frame table plus its metadata."""
    specs = plan_runs(seed)
    rows: list[dict[str, float | str]] = []
    empty_runs: list[str] = []
    for spec in specs:
        run_rows = simulate_run(spec)
        if not run_rows:
            empty_runs.append(spec.run_id)
        rows.extend(run_rows)

    frame = pd.DataFrame(rows, columns=list(METADATA_COLUMNS) + list(FEATURE_ORDER))
    metadata = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "seed": seed,
        "schema": {"metadata_columns": list(METADATA_COLUMNS), "feature_order": list(FEATURE_ORDER)},
        "parameters": {
            "warmup_dt_s": WARMUP_DT_S,
            "sample_dt_s": SAMPLE_DT_S,
            "sample_stride": SAMPLE_STRIDE,
            "frames_per_run": FRAMES_PER_RUN,
            "max_sample_ticks": MAX_SAMPLE_TICKS,
            "developed_fraction": DEVELOPED_FRACTION,
            "sensor_lie_sigma": SENSOR_LIE_SIGMA,
            "rpm_choices": list(RPM_CHOICES),
            "valve_choices": list(VALVE_CHOICES),
            "warmup_choices_s": list(WARMUP_CHOICES),
            "severity_choices": list(SEVERITY_CHOICES),
            "cavitation_severity_choices": list(CAVITATION_SEVERITY_CHOICES),
            "dry_run_severity_choices": list(DRY_RUN_SEVERITY_CHOICES),
            "sensor_modes": list(SENSOR_MODES),
            "sensor_modes_excluded": {
                "freeze": "a frozen transmitter reads correctly under steady conditions; only "
                "detectable across time, and this feature vector is a single frame"
            },
            "sensor_tags": list(SENSOR_TAGS),
            "sensor_tags_excluded": dict(SENSOR_TAGS_EXCLUDED),
            "runs_per_class": dict(RUNS_PER_CLASS),
        },
        "runs_planned": len(specs),
        "runs_with_no_usable_frames": empty_runs,
        "row_count": int(len(frame)),
        "class_counts": {str(k): int(v) for k, v in frame["label"].value_counts().items()},
        "runs_per_class_realised": {
            str(k): int(v) for k, v in frame.groupby("label")["run_id"].nunique().items()
        },
        "source": "app.simulation.engine.SimulationSession, vibration hook not attached",
        "caveat": "Synthetic data from a physics simulator. Not plant measurements.",
    }
    return frame, metadata


def save_dataset(
    frame: pd.DataFrame, metadata: dict, directory: Path | str = DEFAULT_DATA_DIR
) -> tuple[Path, Path]:
    """Write the CSV and its metadata sidecar, creating the directory if needed."""
    target = Path(directory)
    target.mkdir(parents=True, exist_ok=True)
    dataset_path = target / DATASET_FILENAME
    metadata_path = target / METADATA_FILENAME
    frame.to_csv(dataset_path, index=False)
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return dataset_path, metadata_path


def load_dataset(directory: Path | str = DEFAULT_DATA_DIR) -> tuple[pd.DataFrame, dict]:
    """Read a previously generated dataset and its metadata."""
    target = Path(directory)
    frame = pd.read_csv(target / DATASET_FILENAME)
    metadata = json.loads((target / METADATA_FILENAME).read_text(encoding="utf-8"))
    return frame, metadata


def generate(
    directory: Path | str = DEFAULT_DATA_DIR, seed: int = DATASET_SEED
) -> tuple[pd.DataFrame, dict]:
    """Build and persist the dataset. The entry point `train.py` calls."""
    frame, metadata = build_dataset(seed)
    dataset_path, metadata_path = save_dataset(frame, metadata, directory)
    metadata["dataset_path"] = str(dataset_path)
    metadata["metadata_path"] = str(metadata_path)
    metadata_path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return frame, metadata


def _main() -> None:  # pragma: no cover - convenience entry point
    import argparse

    parser = argparse.ArgumentParser(description="Generate the PumpGuard DT training dataset.")
    parser.add_argument("--output", default=str(DEFAULT_DATA_DIR), help="directory for the dataset")
    parser.add_argument("--seed", type=int, default=DATASET_SEED)
    args = parser.parse_args()

    frame, metadata = generate(args.output, args.seed)
    print(f"rows: {len(frame)}  runs: {metadata['runs_planned']}")
    for label, count in sorted(metadata["class_counts"].items()):
        print(f"  {label:18s} {count:6d}")


if __name__ == "__main__":  # pragma: no cover
    _main()


__all__ = [
    "DATASET_SEED",
    "RunSpec",
    "build_dataset",
    "generate",
    "load_dataset",
    "plan_runs",
    "save_dataset",
    "simulate_run",
]
